// Adapt these accessors to your existing flow's message shape.
// The defaults assume:
//   - msg.kind        ← 'weekday' | 'week-end' | 'week-start' (set by your prompt-builder fn)
//   - msg.text        ← the assembled prompt string (output of prompt-weekday.js etc.)
//   - msg.response    ← the Gemini final text response
//   - msg.conv_id     ← HA conversation_id, if available; else falls back to timestamp

const record = {
    ts: new Date().toISOString(),
    kind: msg.kind || 'unknown',
    conv_id: msg.conv_id || msg.payload?.conversation_id || ('ts-' + Date.now()),
    prompt: msg.text || msg.payload?.prompt || '',
    response: msg.response || msg.payload?.response || msg.payload || '',
};

// File-out node wants a string payload; JSONL = one record per line.
msg.payload = JSON.stringify(record);

// Daily-rotated filename. Same dir as the MCP tracer.
const today = new Date().toISOString().slice(0, 10);
msg.filename = `/config/aula-train/conv-${today}.jsonl`;
return msg;
